const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const state = {token:sessionStorage.getItem('sab_token'), user:null, page:'dashboard', products:[], customers:[], sales:[], cart:new Map()};
const navAdmin=[['dashboard','⌂','Overview'],['sales','▤','Sales & invoices'],['products','◇','Products & stock'],['customers','♙','Customers'],['suppliers','♧','Suppliers'],['purchases','▣','Purchases'],['staff','♧','Admin panel'],['support','✉','Developer support'],['attendance','◷','Attendance'],['reports','▥','Reports'],['settings','⚙','Business settings'],['backup','⤓','Backup & restore']];
const navStaff=[['dashboard','⌂','My desk'],['sales','▤','My orders'],['products','◇','Product lookup'],['customers','♙','Customers'],['support','✉','Developer support'],['attendance','◷','Attendance']];
const money=n=>'Rs. '+(Number(n||0)/100).toLocaleString('en-PK',{minimumFractionDigits:2,maximumFractionDigits:2});
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(path,options={}){
  const headers={'Content-Type':'application/json',...(options.headers||{})};
  if(state.token) headers.Authorization=`Bearer ${state.token}`;
  const res=await fetch('/api'+path,{...options,headers});
  let data={}; try{data=await res.json()}catch{}
  if(res.status===401&&path!='/login'){logout(false);throw Error('Session khatam ho gaya. Dobara login karein.')}
  if(!res.ok) throw Error(data.error||'Request poori nahin ho saki.');
  return data;
}
function toast(message,error=false){const el=document.createElement('div');el.className='toast'+(error?' error':'');el.textContent=message;$('#toastHost').append(el);setTimeout(()=>el.remove(),3500)}
function showLogin(){ $('#loginView').classList.remove('hidden');$('#appView').classList.add('hidden') }
function showApp(){ $('#loginView').classList.add('hidden');$('#appView').classList.remove('hidden');$('#userName').textContent=state.user.display_name;$('#userRole').textContent=state.user.role+' access';$('#avatar').textContent=state.user.display_name.slice(0,1).toUpperCase(); renderNav(); navigate(state.user.must_change_password?'staff':state.page||'dashboard') }
async function boot(){ if(location.protocol==='file:'){showLogin();$('#loginError').textContent='Website ko direct index.html khol kar nahi chalaya ja sakta. README-START-HERE.md ke mutabiq Python server start karein, phir http://127.0.0.1:8765 kholein.';return} if(!state.token){showLogin();return} try{state.user=await api('/me');showApp()}catch{showLogin()} }
$('#loginForm').addEventListener('submit',async e=>{e.preventDefault();$('#loginError').textContent='';const fd=new FormData(e.currentTarget);try{const data=await api('/login',{method:'POST',body:JSON.stringify({username:fd.get('username'),password:fd.get('password')})});state.token=data.token;sessionStorage.setItem('sab_token',data.token);state.user=data.user;showApp()}catch(err){$('#loginError').textContent=err.message}});
function logout(call=true){const old=state.token;state.token=null;state.user=null;sessionStorage.removeItem('sab_token');if(call&&old)fetch('/api/logout',{method:'POST',headers:{Authorization:'Bearer '+old}}).catch(()=>{});showLogin()}
$('#logoutBtn').addEventListener('click',()=>logout());
function renderNav(){const items=state.user.role==='admin'?navAdmin:navStaff;$('#nav').innerHTML=items.map(([id,icon,label])=>`<button class="nav-link ${state.page===id?'active':''}" data-page="${id}"><span class="nav-icon">${icon}</span><span class="nav-label">${label}</span>${id==='sales'?`<span class="nav-count">${state.sales.length||''}</span>`:''}</button>`).join('');$$('.nav-link').forEach(b=>b.onclick=()=>navigate(b.dataset.page))}
function navigate(page){state.page=page;renderNav();const labels={dashboard:'Overview',sales:'Sales & invoices',products:'Products & stock',customers:'Customers',suppliers:'Suppliers',purchases:'Purchases',staff:'Admin panel',support:'Developer support',attendance:'Attendance',reports:'Reports',settings:'Business settings',backup:'Backup & restore'};$('#pageCrumb').textContent=labels[page]||page;({dashboard:dashboardPage,sales:salesPage,products:productsPage,customers:customersPage,suppliers:suppliersPage,purchases:purchasesPage,staff:staffPage,support:supportPage,attendance:attendancePage,reports:reportsPage,settings:settingsPage,backup:backupPage}[page]||dashboardPage)()}
$('#quickSale').onclick=()=>openOrder();
function heading(title,subtitle,action=''){return `<div class="page-heading"><div><div class="eyebrow dark">S.A.B TRADER / ${esc(state.user.role.toUpperCase())}</div><h1>${title}</h1><p>${subtitle}</p></div><div class="heading-actions">${action}</div></div>`}
function stat(label,value,note,icon){return `<div class="stat-card"><div class="stat-label">${label}<span class="stat-icon">${icon}</span></div><div class="stat-value">${value}</div><div class="stat-note">${note}</div></div>`}
async function dashboardPage(){const page=$('#page');page.innerHTML=heading(state.user.role==='admin'?'Good business, in balance.':'Welcome to your desk','Here is what is happening in your business today.')+'<div class="empty">Loading your business data…</div>';try{const d=await api('/dashboard');if(state.user.role==='staff'){page.innerHTML=heading('Your work, at a glance','Create orders and customers. Your records stay on this device while the local server is available.',`<button class="button primary" id="dashOrder">＋ New order</button>`)+`<div class="stats-grid">${stat('YOUR RECENT ORDERS',d.my_orders.length,d.my_orders.length?'Orders you created':'No orders yet','▤')}${stat('ACCESS LEVEL','Staff','Assigned workflows only','♙')}</div><section class="panel"><div class="panel-header"><div><div class="panel-title">Your recent orders</div><div class="panel-subtitle">Most recent first</div></div></div>${salesTable(d.my_orders)}</section>`;$('#dashOrder').onclick=()=>openOrder();return}
page.innerHTML=heading('Good business, in balance.','Here is what is happening in your business today.',`<button class="button primary" id="dashOrder">＋ New order</button>`)+`<div class="stats-grid">${stat('TODAY’S SALES',money(d.today_sales_paisa),'Completed invoices today','↗')}${stat('TODAY’S ORDERS',d.today_orders,'Posted sales invoices','▤')}${stat('ACTIVE CUSTOMERS',d.customers,'Across your business','♙')}${stat('PRODUCTS',d.products,'In the catalog','◇')}</div><div class="stats-grid">${stat('CUSTOMER OUTSTANDING',money(d.outstanding_paisa),'Open sale balances','◷')}${stat('SUPPLIER PAYABLES',money(d.supplier_payables_paisa),'Open purchase balances','▣')}${stat('LOW STOCK',d.low_stock,d.low_stock?'Review replenishment':'All stock levels healthy','!')}${stat('DATABASE HEALTH',esc(d.db_health),'SQLite integrity status','✓')}${stat('LAST BACKUP',d.last_backup?new Date(d.last_backup).toLocaleDateString():'Not yet created','Keep a second copy on USB','⤓')}</div><div class="dashboard-grid"><section class="panel"><div class="panel-header"><div><div class="panel-title">Recent invoices</div><div class="panel-subtitle">Latest business activity</div></div><button class="text-button" id="allSales">VIEW ALL →</button></div>${salesTable(d.recent)}</section><section class="panel"><div class="panel-header"><div><div class="panel-title">Business health</div><div class="panel-subtitle">Local records and daily operations</div></div></div><div class="health-row"><span class="health-label">Database</span><span class="badge">${esc(d.db_health)}</span></div><div class="health-row"><span class="health-label">Low stock alerts</span><span class="health-value">${d.low_stock}</span></div><div class="health-row"><span class="health-label">Customer balances</span><span class="health-value">${money(d.outstanding_paisa)}</span></div><div class="health-row"><span class="health-label">Last successful backup</span><span class="health-value">${d.last_backup?new Date(d.last_backup).toLocaleString():'Not created'}</span></div><div class="settings-note" style="margin-top:14px">Business records are saved to this computer’s SQLite database. Back up to a second owner-controlled drive regularly.</div></section></div>`;$('#dashOrder').onclick=()=>openOrder();$('#allSales').onclick=()=>navigate('sales')
}catch(e){page.innerHTML=heading('Dashboard','Business overview')+`<div class="panel empty">${esc(e.message)}</div>`}}
function salesTable(rows){if(!rows?.length)return '<div class="empty">There are no invoices to show yet.</div>';return `<div class="table-wrap"><table><thead><tr><th>INVOICE</th><th>CUSTOMER</th><th>DATE</th><th>TOTAL</th><th>STATUS</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td class="product-name">${esc(r.invoice_number)}</td><td>${esc(r.customer_name_snapshot||'—')}</td><td>${new Date(r.sold_at).toLocaleDateString()}</td><td class="money">${money(r.total_paisa)}</td><td>${r.status?`<span class="badge ${r.status==='posted'?'':'red'}">${esc(r.status)}</span>`:'—'}</td><td><button class="text-button" data-receipt="${esc(r.id)}">VIEW</button>${state.user.role==='admin'&&r.status==='posted'?` <button class="text-button" data-reverse-sale="${esc(r.id)}" data-status="cancelled">CANCEL</button> <button class="text-button" data-reverse-sale="${esc(r.id)}" data-status="returned">RETURN</button>`:''}</td></tr>`).join('')}</tbody></table></div>`}
function bindReceipts(root=$('#page')){$$('[data-receipt]',root).forEach(b=>b.onclick=()=>showReceipt(b.dataset.receipt));$$('[data-reverse-sale]',root).forEach(b=>b.onclick=async()=>{const returned=b.dataset.status==='returned';if(!window.confirm(`Yeh sale ${returned?'returned':'cancelled'} mark hogi aur stock wapas ledger mein add hoga. Agar payment recorded hai to pehle usay reverse karna hoga. Jari rakhein?`))return;try{await api(`/sales/${b.dataset.reverseSale}/reverse`,{method:'POST',body:JSON.stringify({status:b.dataset.status})});toast(`Sale ${returned?'returned':'cancelled'} aur stock reverse ho gaya`);salesPage()}catch(e){toast(e.message,true)}})}
async function salesPage(){const page=$('#page');page.innerHTML=heading('Sales & invoices','Completed sales, invoice history, and receipt reprints.',`<button class="button primary" id="newSale">＋ New order</button>`)+`<div class="panel"><div class="table-toolbar"><label class="search"><input id="salesSearch" placeholder="Search invoices, customers…"></label><span class="toolbar-note">Most recent invoices first</span></div><div id="salesTable"></div></div>`;try{state.sales=await api('/sales');renderSales(state.sales);$('#newSale').onclick=()=>openOrder();$('#salesSearch').oninput=e=>renderSales(state.sales.filter(r=>(r.invoice_number+r.customer_name_snapshot).toLowerCase().includes(e.target.value.toLowerCase())))}catch(e){toast(e.message,true)}}
function renderSales(rows){$('#salesTable').innerHTML=salesTable(rows);bindReceipts($('#salesTable'))}
async function productsPage(){const page=$('#page');page.innerHTML=heading('Products & stock','Catalog, wholesale prices, and stock-on-hand lookup.',state.user.role==='admin'?`<button class="button primary" id="addProduct">＋ Add product</button>`:'')+`<section class="panel"><div class="table-toolbar"><label class="search"><input id="productSearch" placeholder="Search product, brand, SKU or barcode…"></label><span class="toolbar-note" id="productCount"></span></div><div id="productTable"></div></section>`;$('#addProduct')?.addEventListener('click',openProduct);$('#productSearch').oninput=e=>renderProducts(state.products.filter(p=>(p.name+' '+p.sku+' '+p.barcode+' '+(p.brand||'')+' '+(p.category||'')).toLowerCase().includes(e.target.value.toLowerCase())));try{state.products=await api('/products');renderProducts(state.products)}catch(e){toast(e.message,true)}}
function renderProducts(rows){$('#productCount').textContent=`${rows.length} products`;$('#productTable').innerHTML=rows.length?`<div class="table-wrap"><table><thead><tr><th>PRODUCT</th><th>SKU / BARCODE</th><th>CATEGORY</th><th>WHOLESALE</th><th>STOCK</th><th>STATUS</th>${state.user.role==='admin'?'<th></th>':''}</tr></thead><tbody>${rows.map(p=>`<tr><td><span class="product-name">${esc(p.name)}</span><div class="subtext">${esc(p.brand||p.unit)}</div></td><td>${esc(p.sku||p.barcode||'—')}</td><td>${esc(p.category||'—')}</td><td class="money">${money(p.wholesale_price_paisa)}</td><td><span class="${p.stock_quantity<=p.minimum_stock?'badge warn':'badge neutral'}">${p.stock_quantity} ${esc(p.unit)}</span></td><td><span class="badge ${p.active?'':'red'}">${p.active?'Active':'Archived'}</span></td>${state.user.role==='admin'?`<td><button class="text-button" data-adjust-stock="${esc(p.id)}">STOCK</button> <button class="text-button" data-edit-product="${esc(p.id)}">EDIT</button> <button class="text-button" data-record-action="products" data-id="${esc(p.id)}" data-active="${p.active?1:0}">${p.active?'DELETE':'RESTORE'}</button></td>`:''}</tr>`).join('')}</tbody></table></div>`:'<div class="empty">No products yet. Add your first catalog item.</div>';$$('[data-edit-product]').forEach(b=>b.onclick=()=>openProduct(state.products.find(p=>p.id===b.dataset.editProduct)));$$('[data-adjust-stock]').forEach(b=>b.onclick=()=>openStockAdjust(state.products.find(p=>p.id===b.dataset.adjustStock)))}
async function customersPage(){const page=$('#page');page.innerHTML=heading('Customers','Contact book, current balances, and customer records.',`<button class="button primary" id="addCustomer">＋ Add customer</button>`)+`<section class="panel"><div class="table-toolbar"><label class="search"><input id="customerSearch" placeholder="Search name, phone or area…"></label><span class="toolbar-note" id="customerCount"></span></div><div id="customerTable"></div></section>`;$('#addCustomer').onclick=()=>openCustomer();$('#customerSearch').oninput=e=>renderCustomers(state.customers.filter(c=>(c.name+c.phone+c.area).toLowerCase().includes(e.target.value.toLowerCase())));try{state.customers=await api('/customers');renderCustomers(state.customers)}catch(e){toast(e.message,true)}}
function renderCustomers(rows){$('#customerCount').textContent=`${rows.length} customers`;$('#customerTable').innerHTML=rows.length?`<div class="table-wrap"><table><thead><tr><th>CUSTOMER</th><th>PHONE</th><th>AREA</th>${state.user.role==='admin'?'<th>OUTSTANDING</th>':''}<th>STATUS</th>${state.user.role==='admin'?'<th></th>':''}</tr></thead><tbody>${rows.map(c=>`<tr><td><span class="product-name">${esc(c.name)}</span><div class="subtext">${esc(c.address||'')}</div></td><td>${esc(c.phone||'—')}</td><td>${esc(c.area||'—')}</td>${state.user.role==='admin'?`<td class="money">${money(c.balance_paisa)}</td>`:''}<td><span class="badge ${c.active?'':'red'}">${c.active?'Active':'Archived'}</span></td>${state.user.role==='admin'?`<td><button class="text-button" data-ledger="${esc(c.id)}">LEDGER</button> <button class="text-button" data-record-action="customers" data-id="${esc(c.id)}" data-active="${c.active?1:0}">${c.active?'DELETE':'RESTORE'}</button></td>`:''}</tr>`).join('')}</tbody></table></div>`:'<div class="empty">No customers yet. Create a customer record to get started.</div>';$$('[data-ledger]').forEach(b=>b.onclick=()=>customerLedger(b.dataset.ledger))}
function openModal(title,subtitle,body,footer='',wide=false){$('#modalHost').innerHTML=`<div class="modal-backdrop"><section class="modal ${wide?'wide-modal':''}" role="dialog" aria-modal="true"><header class="modal-header"><div><h2>${title}</h2><p>${subtitle}</p></div><button class="close-button" data-close>×</button></header><div class="modal-body">${body}</div>${footer?`<footer class="modal-footer">${footer}</footer>`:''}</section></div>`;$('.modal-backdrop').addEventListener('click',e=>{if(e.target.classList.contains('modal-backdrop')||e.target.closest('[data-close]'))$('#modalHost').innerHTML=''})}
function modalField(label,name,value='',type='text',required=false,extra=''){return `<label class="field">${label}<input name="${name}" type="${type}" value="${esc(value)}" ${required?'required':''} ${extra}></label>`}
function openCustomer(){const admin=state.user.role==='admin';openModal('Add a customer','Customer details are saved to the local business database.',`<form id="customerForm" class="form-grid">${modalField('Customer / business name','name','', 'text',true)}${modalField('Phone number','phone')}${modalField('Area / market','area')}${admin?modalField('Opening balance (Rs.)','opening','0','number',false,'step="0.01" min="0"'):''}${modalField('Address','address')}${admin?modalField('Credit limit (Rs.)','credit','', 'number',false,'step="0.01" min="0"'):''}<label class="field full">Notes<textarea name="notes"></textarea></label></form>`,`<button class="button secondary" data-close>Cancel</button><button class="button primary" id="saveCustomer">Save customer</button>`);$('#saveCustomer').onclick=async()=>{const f=$('#customerForm');if(!f.reportValidity())return;const d=Object.fromEntries(new FormData(f));if(d.phone?.trim()){try{const matches=await api('/customers?q='+encodeURIComponent(d.phone.trim()));const normalized=d.phone.replace(/\D/g,'');if(matches.some(c=>c.phone&&c.phone.replace(/\D/g,'')===normalized)&&!window.confirm('Is phone number ke saath pehle se customer record maujood hai. Phir bhi naya customer banana hai?'))return}catch(e){toast(e.message,true);return}}d.opening_balance_paisa=Math.round(Number(d.opening||0)*100);d.credit_limit_paisa=d.credit?Math.round(Number(d.credit)*100):null;try{await api('/customers',{method:'POST',body:JSON.stringify(d)});$('#modalHost').innerHTML='';toast('Customer saved');if(state.page==='customers')customersPage()}catch(e){toast(e.message,true)}}}
function openProduct(product=null){const p=product||{};const edit=!!product;openModal(edit?'Edit product':'Add a product',edit?'Update catalog details.': 'Add a catalog item with its opening stock and wholesale price.',`<form id="productForm" class="form-grid">${modalField('Product name','name',p.name||'','text',true)}${modalField('SKU','sku',p.sku||'')}${modalField('Barcode','barcode',p.barcode||'')}${modalField('Unit / pack','unit',p.unit||'piece')}${modalField('Purchase cost (Rs.)','cost',p.purchase_cost_paisa!=null?(p.purchase_cost_paisa/100).toFixed(2):'0','number',false,'min="0" step="0.01"')}${modalField('Wholesale price (Rs.)','price',p.wholesale_price_paisa!=null?(p.wholesale_price_paisa/100).toFixed(2):'','number',true,'min="0" step="0.01"')}${modalField('Retail price (Rs.)','retail',p.retail_price_paisa!=null?(p.retail_price_paisa/100).toFixed(2):'','number',false,'min="0" step="0.01"')}${edit?'':modalField('Opening stock','stock','0','number',true,'min="0" step="1"')}${modalField('Low stock warning at','minimum',p.minimum_stock||'0','number',false,'min="0" step="1"')}${edit?`<label class="field">Status<select name="active"><option value="1" ${p.active?'selected':''}>Active</option><option value="0" ${!p.active?'selected':''}>Archived</option></select></label>`:''}</form>`,`<button class="button secondary" data-close>Cancel</button><button class="button primary" id="saveProduct">${edit?'Save changes':'Add product'}</button>`);$('#saveProduct').onclick=async()=>{const f=$('#productForm');if(!f.reportValidity())return;const d=Object.fromEntries(new FormData(f));d.wholesale_price_paisa=Math.round(Number(d.price)*100);d.purchase_cost_paisa=Math.round(Number(d.cost||0)*100);d.retail_price_paisa=d.retail?Math.round(Number(d.retail)*100):null;d.minimum_stock=Number(d.minimum||0);if(!edit)d.stock_quantity=Number(d.stock||0);else d.active=Number(d.active);try{if(edit)await api('/products/'+p.id,{method:'PUT',body:JSON.stringify(d)});else await api('/products',{method:'POST',body:JSON.stringify(d)});$('#modalHost').innerHTML='';toast(edit?'Product updated':'Product added');productsPage()}catch(e){toast(e.message,true)}}}
function openStockAdjust(p){openModal('Adjust stock',`Current stock: ${p.stock_quantity} ${p.unit}. Every change is recorded in the stock ledger.`,`<form id="stockForm" class="form-grid">${modalField('Quantity change (+ receive / − remove)','quantity_delta','','number',true,'step="1"')}${modalField('Reason','reason','','text',true)}<label class="field full">Notes<textarea name="note"></textarea></label></form>`,`<button class="button secondary" data-close>Cancel</button><button class="button primary" id="saveStock">Record adjustment</button>`);$('#saveStock').onclick=async()=>{const f=$('#stockForm');if(!f.reportValidity())return;const d=Object.fromEntries(new FormData(f));d.quantity_delta=Number(d.quantity_delta);try{await api(`/products/${p.id}/adjust`,{method:'POST',body:JSON.stringify(d)});$('#modalHost').innerHTML='';toast('Stock adjustment recorded');productsPage()}catch(e){toast(e.message,true)}}}
async function openOrder(){try{if(!state.products.length)state.products=await api('/products');if(!state.customers.length)state.customers=await api('/customers')}catch(e){toast(e.message,true);return}state.cart=new Map();const customerOptions=state.customers.filter(c=>c.active).map(c=>`<option value="${esc(c.id)}">${esc(c.name)}${c.phone?' · '+esc(c.phone):''}</option>`).join('');openModal('Create a sales order','A confirmed order deducts stock once and creates a saved invoice.',`<div class="form-grid"><label class="field"><span>Customer</span><select id="orderCustomer"><option value="">Walk-in customer</option>${customerOptions}</select></label><label class="field"><span>Product search</span><input id="orderSearch" placeholder="Product name or SKU"></label></div><div id="cartCatalog" class="cart-products"></div><div style="height:12px"></div><div id="cartSummary"></div>`,`<button class="button secondary" data-close>Cancel</button><button class="button primary" id="completeOrder">Complete sale</button>`,true);renderCartCatalog(state.products);$('#orderSearch').oninput=e=>renderCartCatalog(state.products.filter(p=>(p.name+p.sku).toLowerCase().includes(e.target.value.toLowerCase())));renderCartSummary();$('#completeOrder').onclick=completeOrder}
function renderCartCatalog(rows){$('#cartCatalog').innerHTML=rows.length?rows.map(p=>`<div class="cart-product"><div class="cart-product-info"><strong>${esc(p.name)}</strong><small>${esc(p.sku||p.unit)} · ${p.stock_quantity} in stock · ${money(p.wholesale_price_paisa)}</small></div><button class="button outline compact" data-add-cart="${esc(p.id)}" ${p.stock_quantity<=0?'disabled':''}>Add</button></div>`).join(''):'<div class="empty">No matching products.</div>';$$('[data-add-cart]').forEach(b=>b.onclick=()=>{const p=state.products.find(x=>x.id===b.dataset.addCart);const item=state.cart.get(p.id)||{product:p,quantity:0};if(item.quantity<p.stock_quantity)item.quantity++;state.cart.set(p.id,item);renderCartSummary()})}
function renderCartSummary(){const items=[...state.cart.values()];const total=items.reduce((sum,x)=>sum+x.product.wholesale_price_paisa*x.quantity,0);$('#cartSummary').innerHTML=`<div class="cart-layout"><div>${items.length?items.map(x=>`<div class="cart-product"><div class="cart-product-info"><strong>${esc(x.product.name)}</strong><small>${money(x.product.wholesale_price_paisa)} × ${x.quantity}</small></div><div class="qty-control"><button data-dec="${esc(x.product.id)}">−</button><span>${x.quantity}</span><button data-inc="${esc(x.product.id)}">＋</button></div></div>`).join(''):'<div class="empty">Add products to this order.</div>'}</div><div class="cart-summary"><div class="summary-row"><span>Subtotal</span><b>${money(total)}</b></div>${state.user.role==='admin'?'<label class="field">Invoice discount (Rs.)<input id="orderDiscount" type="number" min="0" step="0.01" value="0"></label>':''}<label class="field">Amount paid (Rs.)<input id="orderPaid" type="number" min="0" step="0.01" value="${(total/100).toFixed(2)}"></label><label class="field">Payment method<select id="paymentMethod"><option>Cash</option><option>Bank transfer</option><option>Other</option></select></label><div class="summary-row total"><span>Net total</span><b id="netTotal">${money(total)}</b></div></div></div>`;$$('[data-dec]').forEach(b=>b.onclick=()=>changeQty(b.dataset.dec,-1));$$('[data-inc]').forEach(b=>b.onclick=()=>changeQty(b.dataset.inc,1));$('#orderDiscount')?.addEventListener('input',()=>{$('#netTotal').textContent=money(total-Math.round(Number($('#orderDiscount').value||0)*100))})}
function changeQty(id,delta){const item=state.cart.get(id);if(!item)return;item.quantity+=delta;if(item.quantity<=0)state.cart.delete(id);if(item.quantity>item.product.stock_quantity)item.quantity=item.product.stock_quantity;renderCartSummary()}
async function completeOrder(){const items=[...state.cart.values()];if(!items.length){toast('Order mein kam az kam aik product add karein.',true);return}const subtotal=items.reduce((s,x)=>s+x.product.wholesale_price_paisa*x.quantity,0);const discount=Math.round(Number($('#orderDiscount')?.value||0)*100);const total=subtotal-discount;const paid=Math.round(Number($('#orderPaid')?.value||0)*100);if(total<0||paid<0||paid>total){toast('Discount ya paid amount durust nahin.',true);return}const payload={id:crypto.randomUUID(),customer_id:$('#orderCustomer').value||null,items:items.map(x=>({product_id:x.product.id,quantity:x.quantity,unit_price_paisa:x.product.wholesale_price_paisa})),discount_paisa:discount,paid_paisa:paid,payment_method:$('#paymentMethod').value};try{const result=await api('/sales',{method:'POST',body:JSON.stringify(payload)});$('#modalHost').innerHTML='';toast(result.duplicate?'Yeh order pehle hi save ho chuka hai.':'Order saved · '+result.invoice_number);state.products=[];state.customers=[];if(state.page==='sales')salesPage();showReceipt(result.id)}catch(e){toast(e.message,true)}}
async function showReceipt(id){try{const r=await api('/receipt/'+encodeURIComponent(id));const s=r.settings;const total=`<div class="receipt-total"><span>Subtotal</span><b>${money(r.subtotal_paisa)}</b></div><div class="receipt-total"><span>Discount</span><b>− ${money(r.discount_paisa)}</b></div><div class="receipt-total net"><span>NET TOTAL</span><b>${money(r.total_paisa)}</b></div><div class="receipt-total"><span>Paid</span><b>${money(r.paid_paisa)}</b></div><div class="receipt-total"><span>Balance</span><b>${money(r.balance_paisa)}</b></div>`;const body=`<article class="receipt"><header class="receipt-head"><div class="receipt-brand">${esc(s.business_name||'S.A.B TRADER')}</div><div class="receipt-type">${esc(s.business_type||'COSMETICS WHOLESALE & SUPPLY')}</div><div class="receipt-phone">Phone: ${esc(s.company_phone||'03336447526')}</div>${s.business_address?`<div class="receipt-phone">${esc(s.business_address)}</div>`:''}</header><div class="receipt-rule"></div><div class="receipt-title">SALES INVOICE</div><div class="receipt-meta">Invoice: ${esc(r.invoice_number)}<br>Date: ${new Date(r.sold_at).toLocaleDateString()} · ${new Date(r.sold_at).toLocaleTimeString()}<br>Customer: ${esc(r.customer_name_snapshot)}<br>${r.customer_phone_snapshot?'Phone: '+esc(r.customer_phone_snapshot)+'<br>':''}Staff: ${esc(r.staff_name)}</div><div class="receipt-rule"></div>${r.items.map(i=>`<div class="receipt-item"><div class="receipt-item-name">${esc(i.product_name_snapshot)}</div><div class="receipt-item-line"><span>${i.quantity} × ${money(i.unit_price_paisa)}</span><b>${money(i.line_total_paisa)}</b></div></div>`).join('')}<div class="receipt-rule"></div>${total}<div class="receipt-total"><span>Payment</span><b>${esc(r.payment_method)}</b></div><div class="receipt-rule"></div><div class="receipt-footer">${esc(s.receipt_footer||'Thank you for shopping with S.A.B Trader!')}<br>Please keep your receipt for reference.<div class="receipt-rule"></div>${s.developer_footer_enabled!=='false'?`SOFTWARE BY<strong>${esc(s.developer_brand||'WEB BY ZAINI')}</strong>Developer Contact: ${esc(s.developer_phone||'03327021212')}`:''}</div></article>`;openModal('Invoice '+esc(r.invoice_number),'Saved invoice snapshot · reprinting does not post another sale.',body,`<button class="button secondary" data-close>Close</button><button class="button primary" id="printReceipt">Print receipt</button>`);$('#printReceipt').onclick=()=>window.print()}catch(e){toast(e.message,true)}}
async function supportPage(){
  const page=$('#page');
  page.innerHTML=heading('Developer support','Report a problem, request help, or send a feature suggestion.',`<button class="button primary" id="newSupport">＋ New request</button>`)+`<section class="panel"><div class="settings-note">Support requests are saved in this app. Use WhatsApp to contact WEB BY ZAINI directly. Replies from WhatsApp do not sync automatically; Admin can add the solution here so it appears in request history.</div><div id="supportTable" class="empty" style="margin-top:18px">Loading requests…</div></section>`;
  $('#newSupport').onclick=openSupportRequest;
  try{
    const rows=await api('/support');
    $('#supportTable').innerHTML=rows.length?`<div class="table-wrap"><table><thead><tr>${state.user.role==='admin'?'<th>REQUESTER</th>':''}<th>TICKET</th><th>TYPE / REQUEST</th><th>STATUS</th><th>CREATED</th><th>DETAILS</th><th>ACTION</th></tr></thead><tbody>${rows.map(t=>{const msg=`S.A.B Trader support request ${t.ticket_number}\n${t.category}: ${t.subject}\n${t.message}`;return `<tr>${state.user.role==='admin'?`<td>${esc(t.requester_name)}</td>`:''}<td class="product-name">${esc(t.ticket_number)}</td><td>${esc(t.category)}<div class="subtext">${esc(t.subject)}</div></td><td><span class="badge ${t.status==='resolved'||t.status==='closed'?'':'warn'}">${esc(t.status.replace('_',' '))}</span></td><td>${new Date(t.created_at).toLocaleString()}</td><td><button class="text-button" data-ticket-view="${esc(t.id)}">VIEW</button></td><td><a class="text-button" href="https://wa.me/923327021212?text=${encodeURIComponent(msg)}" target="_blank" rel="noopener">WHATSAPP</a>${state.user.role==='admin'?` <button class="text-button" data-ticket-reply="${esc(t.id)}">ADD SOLUTION</button>`:''}</td></tr>`}).join('')}</tbody></table></div>`:'<div class="empty">Abhi koi support request nahi. New request se shuru karein.</div>';
    $('[data-ticket-view]').forEach(b=>b.onclick=()=>{const t=rows.find(x=>x.id===b.dataset.ticketView);alert(`${t.ticket_number} · ${t.status}\n\n${t.message}${t.developer_reply?'\n\nSolution:\n'+t.developer_reply:''}`)});
    $('[data-ticket-reply]').forEach(b=>b.onclick=async()=>{const t=rows.find(x=>x.id===b.dataset.ticketReply),reply=prompt('Developer ka solution / response yahan enter karein:',t.developer_reply||'');if(reply===null||!reply.trim())return;try{await api(`/support/${t.id}/reply`,{method:'POST',body:JSON.stringify({developer_reply:reply.trim(),status:'resolved'})});toast('Solution ticket mein save ho gaya');supportPage()}catch(e){toast(e.message,true)}})
  }catch(e){toast(e.message,true)}
}
function openSupportRequest(){
  openModal('Developer support request','Complaint, technical help, account issue, ya feature request bhejein.',`<form id="supportForm" class="form-grid"><label class="field">Request type<select name="category"><option>Complaint</option><option>Technical issue</option><option>Account help</option><option>Feature request</option><option>Other</option></select></label>${modalField('Short subject','subject','','text',true,'maxlength="120"')}<label class="field full">Details<textarea name="message" required maxlength="3000" rows="5" placeholder="Masla kab shuru hua, aur kya steps kiye? Password ya payment card details yahan na likhein."></textarea></label></form>`,`<button class="button secondary" data-close>Cancel</button><button class="button primary" id="sendSupport">Save request</button>`);
  $('#sendSupport').onclick=async()=>{const f=$('#supportForm');if(!f.reportValidity())return;try{const ticket=await api('/support',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(f)))});$('#modalHost').innerHTML='';toast('Request '+ticket.ticket_number+' save ho gayi. WhatsApp action se developer ko bhejein.');supportPage()}catch(e){toast(e.message,true)}}
}

async function attendancePage(){const page=$('#page');page.innerHTML=heading('Attendance','Check in and out. Records are timestamped and linked to your account.',`<button class="button primary" id="checkIn">Check in</button><button class="button secondary" id="checkOut">Check out</button>`)+`<section class="panel"><div class="panel-header"><div><div class="panel-title">Attendance history</div><div class="panel-subtitle">${state.user.role==='admin'?'Business-wide staff records':'Your attendance records'}</div></div></div><div id="attendanceTable"><div class="empty">Loading records…</div></div></section>`;$('#checkIn').onclick=()=>attendanceAction('check-in');$('#checkOut').onclick=()=>attendanceAction('check-out');try{const a=await api('/attendance');$('#attendanceTable').innerHTML=a.length?`<div class="table-wrap"><table><thead><tr>${state.user.role==='admin'?'<th>STAFF</th>':''}<th>CHECKED IN</th><th>CHECKED OUT</th><th>STATUS</th></tr></thead><tbody>${a.map(x=>`<tr>${state.user.role==='admin'?`<td>${esc(x.display_name)}</td>`:''}<td>${new Date(x.checked_in_at).toLocaleString()}</td><td>${x.checked_out_at?new Date(x.checked_out_at).toLocaleString():'—'}</td><td><span class="badge ${x.checked_out_at?'neutral':'warn'}">${x.checked_out_at?'Complete':'Open shift'}</span></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No attendance records yet.</div>'}catch(e){toast(e.message,true)}}
async function attendanceAction(action){try{await api('/attendance/'+action,{method:'POST',body:'{}'});toast(action==='check-in'?'Checked in':'Checked out');attendancePage()}catch(e){toast(e.message,true)}}
async function reportsPage(){const page=$('#page');page.innerHTML=heading('Reports','Date-filtered sales and inventory summaries.','')+`<div class="stats-grid">${stat('SALES REPORT','—','Choose a date period','▥')}${stat('STOCK ON HAND','—','Current catalog quantities','◇')}${stat('CUSTOMER BALANCES','—','Open receivables','♙')}${stat('SALES BY STAFF','—','Completed invoices','◷')}</div><section class="panel"><div class="table-toolbar"><label class="field">From<input id="reportFrom" type="date"></label><label class="field">To<input id="reportTo" type="date"></label><button class="button primary" id="runReport">Run report</button><button class="button secondary" id="exportCsv">Export visible sales CSV</button></div><div id="reportBody" class="empty">Select a date range to calculate sales from saved invoices.</div></section>`;$('#runReport').onclick=runReport;$('#exportCsv').onclick=exportSales}
async function runReport(){try{const [rows,products]=await Promise.all([api('/sales'),api('/products')]);state.products=products;const from=$('#reportFrom').value,to=$('#reportTo').value;const selected=rows.filter(r=>{const d=r.sold_at.slice(0,10);return(!from||d>=from)&&(!to||d<=to)});const sum=selected.reduce((n,r)=>n+r.total_paisa,0);$('#reportBody').innerHTML=`<div class="stats-grid">${stat('INVOICES',selected.length,'Within selected date range','▤')}${stat('NET SALES',money(sum),'Total of completed invoices','↗')}${stat('AVERAGE ORDER',selected.length?money(Math.round(sum/selected.length)):money(0),'Net sales divided by invoice count','◷')}${stat('LOW STOCK',products.filter(p=>p.stock_quantity<=p.minimum_stock).length,'Current catalog warning count','!')}</div>${salesTable(selected)}`;bindReceipts($('#reportBody'));state.reportRows=selected}catch(e){toast(e.message,true)}}
function exportSales(){const rows=state.reportRows||state.sales;if(!rows.length){api('/sales').then(r=>{state.reportRows=r;exportSales()});return}const lines=[['Invoice','Customer','Date','Total PKR','Status'],...rows.map(r=>[r.invoice_number,r.customer_name_snapshot,r.sold_at,(r.total_paisa/100).toFixed(2),r.status||'posted'])];const csv=lines.map(row=>row.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\r\n');const link=document.createElement('a');link.href=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv'}));link.download='sab-trader-sales.csv';link.click();URL.revokeObjectURL(link.href)}
async function settingsPage(){const page=$('#page');page.innerHTML=heading('Business settings','Edit the business identity and receipt preferences.',`<button class="button primary" id="saveSettings">Save settings</button>`)+`<div class="settings-grid"><section class="panel"><div class="panel-title">Business identity</div><div class="panel-subtitle">Only enter details provided by the business owner.</div><form id="settingsForm" class="form-grid" style="margin-top:18px"><label class="field">Business name<input name="business_name"></label><label class="field">Business type<input name="business_type"></label><label class="field">Company phone<input name="company_phone"></label><label class="field">Currency<input name="currency"></label><label class="field full">Address (optional)<input name="business_address" placeholder="Not set"></label><label class="field">Email (optional)<input name="business_email"></label><label class="field">Timezone<input name="timezone"></label><label class="field">Invoice prefix<input name="invoice_prefix"></label><label class="field">Receipt width<select name="receipt_width_mm"><option>80</option><option>58</option></select></label><label class="field full">Receipt footer<input name="receipt_footer"></label><label class="field full"><span><input type="checkbox" name="developer_footer_enabled" style="width:auto"> Show WEB BY ZAINI developer footer</span></label></form></section><section class="panel"><div class="panel-title">Data & receipt defaults</div><div class="panel-subtitle">Your local-first business setup</div><div class="health-row"><span class="health-label">Database path</span><span class="health-value" id="dbPathDisplay">Loading…</span></div><div class="health-row"><span class="health-label">Backup folder</span><span class="health-value" id="backupPathDisplay">Loading…</span></div><div class="health-row"><span class="health-label">Primary receipt roll</span><span class="health-value">80mm thermal</span></div><div class="health-row"><span class="health-label">Business phone</span><span class="health-value">03336447526</span></div><div class="health-row"><span class="health-label">Developer attribution</span><span class="health-value">WEB BY ZAINI · 03327021212</span></div><div class="settings-note" style="margin-top:16px">The local website API binds to this computer by default. If you explicitly enable LAN access for other devices, keep it on a trusted Wi-Fi network. Do not expose the port to the public internet.</div></section></div>`;try{const s=await api('/settings');$('#dbPathDisplay').textContent=s.database_path;$('#backupPathDisplay').textContent=s.backup_path;const f=$('#settingsForm');for(const [k,v] of Object.entries(s)){const el=f.elements[k];if(el){if(el.type==='checkbox')el.checked=v!=='false';else el.value=v}}}catch(e){toast(e.message,true)}$('#saveSettings').onclick=async()=>{const f=$('#settingsForm');const data=Object.fromEntries(new FormData(f));data.developer_footer_enabled=f.elements.developer_footer_enabled.checked?'true':'false';try{await api('/settings',{method:'POST',body:JSON.stringify(data)});toast('Business settings saved')}catch(e){toast(e.message,true)}}}
function backupPage(){const page=$('#page');page.innerHTML=heading('Backup & restore','Create a verified copy or restore a compatible SQLite backup.','')+`<div class="settings-grid"><section class="panel"><div class="panel-title">Create a manual backup</div><div class="panel-subtitle">SQLite online backup API with integrity verification.</div><form id="backupForm" style="margin-top:20px"><label class="field">Backup file path<input name="path" placeholder="D:\\SABTrader-Backups\\sabtrader-2026-10-20.sqlite" required></label><div class="settings-note">Keep another copy on an external USB drive or other owner-controlled storage. A backup on the same physical drive does not protect against drive failure.</div><button class="button primary" style="margin-top:17px">Create verified backup</button></form><div class="health-row"><span class="health-label">Last successful backup</span><span class="health-value" id="backupLast">Loading…</span></div></section><section class="panel"><div class="panel-title">Restore from backup</div><div class="panel-subtitle">A safety backup of current data is created before replacement.</div><form id="restoreForm" style="margin-top:20px"><label class="field">Existing backup file path<input name="path" placeholder="D:\\SABTrader-Backups\\sabtrader-backup.sqlite" required></label><div class="settings-note">Restore replaces the active database with the selected backup. The current database is copied to a timestamped safety file first. After restore, sign in again.</div><button class="button danger" style="margin-top:17px">Validate and restore database</button></form><div class="settings-note" style="margin-top:14px">Automatic daily backups need Windows Task Scheduler and the computer powered on at the scheduled time. This website does not create the scheduled task automatically.</div></section></div>`;api('/dashboard').then(d=>$('#backupLast').textContent=d.last_backup?new Date(d.last_backup).toLocaleString():'No backup yet').catch(()=>{});$('#backupForm').onsubmit=async e=>{e.preventDefault();const path=new FormData(e.currentTarget).get('path');try{const r=await api('/backup',{method:'POST',body:JSON.stringify({path})});toast('Backup verified: '+r.filename);backupPage()}catch(err){toast(err.message,true)}};$('#restoreForm').onsubmit=async e=>{e.preventDefault();const path=new FormData(e.currentTarget).get('path');if(!window.confirm('Database is selected backup se replace hoga. Current database ka safety backup pehle banega. Restore jari rakhein?'))return;try{const r=await api('/restore',{method:'POST',body:JSON.stringify({path})});state.token=null;sessionStorage.removeItem('sab_token');state.user=null;showLogin();$('#loginError').textContent='Restore mukammal. Ab restored database ke Admin account se sign in karein. Safety backup: '+r.safety_backup}catch(err){toast(err.message,true)}}}
async function applyRecordAction(button){const kind=button.dataset.recordAction,id=button.dataset.id,active=button.dataset.active==='1';if(kind==='staff'){if(!confirm(active?'Is staff ka access band kar dein? Uski purani sales aur audit history mehfooz rahegi.':'Is staff ka access dobara enable karein?'))return;try{await api('/admin/'+kind+'/'+encodeURIComponent(id),{method:'PATCH',body:JSON.stringify({active:!active})});toast(active?'Staff access remove kar diya':'Staff access restore kar diya');staffPage()}catch(e){toast(e.message,true)}return}if(active){if(!confirm('Record delete karein? Agar is ka sales/purchase/stock history se link hai to permanent delete ke bajaye archive hoga.'))return;try{const result=await api('/admin/'+kind+'/'+encodeURIComponent(id),{method:'DELETE'});toast(result.archived?'Record archive kar diya; history safe hai.':'Record delete kar diya');({products:productsPage,customers:customersPage,suppliers:suppliersPage}[kind])()}catch(e){toast(e.message,true)}}else{if(!confirm('Archived record restore karein?'))return;try{await api('/admin/'+kind+'/'+encodeURIComponent(id),{method:'PATCH',body:JSON.stringify({active:true})});toast('Record restore kar diya');({products:productsPage,customers:customersPage,suppliers:suppliersPage}[kind])()}catch(e){toast(e.message,true)}}}
document.addEventListener('click',e=>{const button=e.target.closest('[data-record-action]');if(button)applyRecordAction(button)});
boot();

async function customerLedger(id){try{const d=await api(`/customer/${id}/ledger`);const c=d.customer;const rows=[...d.sales.map(s=>({date:s.sold_at,type:'Invoice '+s.invoice_number,amount:s.total_paisa})),...d.payments.map(p=>({date:p.paid_at,type:(p.reversal_of?'Reversal ':'Payment ')+p.payment_number,amount:p.reversal_of?p.amount_paisa:-p.amount_paisa,paymentId:p.id,reversible:!p.reversal_of}))].sort((a,b)=>b.date.localeCompare(a.date));const body=`<div class="stats-grid">${stat('CURRENT BALANCE',money(d.balance_paisa),'Receivable balance','◷')}${stat('TOTAL INVOICES',d.sales.length,'Saved sales records','▤')}</div><div class="table-wrap"><table><thead><tr><th>DATE</th><th>ENTRY</th><th>AMOUNT</th><th></th></tr></thead><tbody>${rows.map(r=>`<tr><td>${new Date(r.date).toLocaleString()}</td><td>${esc(r.type)}</td><td class="money">${money(r.amount)}</td><td>${r.reversible?`<button class="text-button" data-reverse-payment="${esc(r.paymentId)}">REVERSE</button>`:''}</td></tr>`).join('')||'<tr><td colspan="4">No ledger entries yet.</td></tr>'}</tbody></table></div><div style="height:16px"></div><form id="paymentForm" class="form-grid">${modalField('Record customer payment (Rs.)','amount','','number',true,'min="0.01" step="0.01"')}<label class="field">Method<select name="method"><option>Cash</option><option>Bank transfer</option><option>Other</option></select></label>${modalField('Note','note')}</form>`;openModal('Customer ledger · '+esc(c.name),'Invoice and payment history with current balance.',body,`<button class="button secondary" data-close>Close</button><button class="button primary" id="recordPayment">Record payment</button>`,true);$$('[data-reverse-payment]').forEach(b=>b.onclick=async()=>{if(!window.confirm('Yeh payment reverse hogi aur customer balance mein wapas add hogi. Jari rakhein?'))return;try{await api(`/payments/${b.dataset.reversePayment}/reverse`,{method:'POST',body:'{}'});$('#modalHost').innerHTML='';toast('Payment reversal recorded');customerLedger(id)}catch(e){toast(e.message,true)}});$('#recordPayment').onclick=async()=>{const f=$('#paymentForm');if(!f.reportValidity())return;const p=Object.fromEntries(new FormData(f));p.id=crypto.randomUUID();p.customer_id=id;p.amount_paisa=Math.round(Number(p.amount)*100);try{await api('/payments',{method:'POST',body:JSON.stringify(p)});$('#modalHost').innerHTML='';toast('Customer payment recorded');customersPage()}catch(e){toast(e.message,true)}}}catch(e){toast(e.message,true)}}
async function staffPage(){const page=$('#page');page.innerHTML=heading('Admin panel','Admin account settings and staff access.',`<button class="button primary" id="newStaff">＋ Add staff</button>`)+`<section class="panel"><div class="panel-title">Admin username & password</div><p class="panel-subtitle">Password change ke liye current password dein. Naya password kam az kam 12 characters ka hona chahiye.</p><form id="credentialForm" class="form-grid" style="margin-top:16px"><label class="field">Admin username<input name="username" value="${esc(state.user.username||'admin')}" minlength="3" maxlength="64" required></label><label class="field">Current password<input name="current_password" type="password" required autocomplete="current-password"></label><label class="field">New password<input name="new_password" type="password" minlength="12" ${state.user.must_change_password?'required':''} autocomplete="new-password"></label><label class="field">Confirm new password<input name="confirm_password" type="password" minlength="12" ${state.user.must_change_password?'required':''} autocomplete="new-password"></label><div class="field full"><button class="button secondary" type="submit">Save admin login</button></div></form></section><section class="panel"><div class="panel-header"><div><div class="panel-title">Staff accounts</div><div class="panel-subtitle">Remove access immediately or restore it later. Historical transactions stay linked.</div></div></div><div id="staffTable" class="empty">Loading accounts…</div></section>`;$('#newStaff').onclick=openStaffCreate;$('#credentialForm').onsubmit=async e=>{e.preventDefault();const f=e.currentTarget;if(!f.reportValidity())return;const d=Object.fromEntries(new FormData(f));if(d.new_password&&d.new_password!==d.confirm_password){toast('New password aur confirmation match nahin huay.',true);return}try{const r=await api('/account',{method:'POST',body:JSON.stringify(d)});state.user={...state.user,...r.user};$('#userName').textContent=state.user.display_name;state.user.must_change_password=false;toast('Admin login update ho gaya');staffPage()}catch(err){toast(err.message,true)}};try{const rows=await api('/staff');$('#staffTable').innerHTML=`<div class="table-wrap"><table><thead><tr><th>NAME</th><th>USERNAME</th><th>ROLE</th><th>STATUS</th><th>CREATED</th><th>ACTIONS</th></tr></thead><tbody>${rows.map(u=>`<tr><td class="product-name">${esc(u.display_name)}</td><td>${esc(u.username)}</td><td><span class="badge neutral">${esc(u.role)}</span></td><td><span class="badge ${u.active?'':'red'}">${u.active?'Active':'Disabled'}</span></td><td>${new Date(u.created_at).toLocaleDateString()}</td><td>${u.role==='staff'?`<button class="text-button" data-record-action="staff" data-id="${esc(u.id)}" data-active="${u.active?1:0}">${u.active?'REMOVE ACCESS':'RESTORE ACCESS'}</button>`:'—'}</td></tr>`).join('')}</tbody></table></div>`}catch(e){toast(e.message,true)}}
function openStaffCreate(){openModal('Create a staff account','Set a unique username and a strong initial password. No shared default credentials are created.',`<form id="staffForm" class="form-grid">${modalField('Display name','display_name','','text',true)}${modalField('Username','username','','text',true)}${modalField('Initial password (minimum 12 characters)','password','','password',true,'minlength="12"')}<div class="settings-note field full">Staff can access product lookup, customer creation, their orders and attendance. Admin settings, backups, reports, staff management and purchase costs remain restricted.</div></form>`,`<button class="button secondary" data-close>Cancel</button><button class="button primary" id="saveStaff">Create account</button>`);$('#saveStaff').onclick=async()=>{const f=$('#staffForm');if(!f.reportValidity())return;try{await api('/staff',{method:'POST',body:JSON.stringify(Object.fromEntries(new FormData(f)))});$('#modalHost').innerHTML='';toast('Staff account created');staffPage()}catch(e){toast(e.message,true)}}}
async function suppliersPage(){const page=$('#page');page.innerHTML=heading('Suppliers','Supplier directory and current payable balances.',`<button class="button primary" id="addSupplier">＋ Add supplier</button>`)+`<section class="panel"><div class="table-toolbar"><label class="search"><input id="supplierSearch" placeholder="Search supplier name or phone…"></label></div><div id="supplierTable"></div></section>`;$('#addSupplier').onclick=openSupplier;$('#supplierSearch').oninput=e=>drawSuppliers(state.suppliers.filter(s=>(s.name+s.phone).toLowerCase().includes(e.target.value.toLowerCase())));try{state.suppliers=await api('/suppliers');drawSuppliers(state.suppliers)}catch(e){toast(e.message,true)}}
function drawSuppliers(rows){$('#supplierTable').innerHTML=rows.length?`<div class="table-wrap"><table><thead><tr><th>SUPPLIER</th><th>PHONE</th><th>OPENING PAYABLE</th><th>CURRENT PAYABLE</th><th>STATUS</th><th>ACTIONS</th></tr></thead><tbody>${rows.map(s=>`<tr><td class="product-name">${esc(s.name)}<div class="subtext">${esc(s.address||'')}</div></td><td>${esc(s.phone||'—')}</td><td class="money">${money(s.opening_balance_paisa)}</td><td class="money">${money(s.balance_paisa)}</td><td><span class="badge ${s.active?'':'red'}">${s.active?'Active':'Archived'}</span></td><td><button class="text-button" data-record-action="suppliers" data-id="${esc(s.id)}" data-active="${s.active?1:0}">${s.active?'DELETE':'RESTORE'}</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No suppliers yet.</div>'}
function openSupplier(){openModal('Add a supplier','Create a supplier contact and opening payable balance.',`<form id="supplierForm" class="form-grid">${modalField('Supplier name','name','','text',true)}${modalField('Phone number','phone')}${modalField('Opening balance (Rs.)','opening','0','number',false,'min="0" step="0.01"')}<label class="field full">Address<input name="address"></label><label class="field full">Notes<textarea name="notes"></textarea></label></form>`,`<button class="button secondary" data-close>Cancel</button><button class="button primary" id="saveSupplier">Save supplier</button>`);$('#saveSupplier').onclick=async()=>{const f=$('#supplierForm');if(!f.reportValidity())return;const p=Object.fromEntries(new FormData(f));p.opening_balance_paisa=Math.round(Number(p.opening||0)*100);try{await api('/suppliers',{method:'POST',body:JSON.stringify(p)});$('#modalHost').innerHTML='';toast('Supplier saved');suppliersPage()}catch(e){toast(e.message,true)}}}
async function purchasesPage(){const page=$('#page');page.innerHTML=heading('Purchases','Record supplier purchases and receive their stock transactionally.',`<button class="button primary" id="newPurchase">＋ Record purchase</button>`)+`<section class="panel"><div class="panel-header"><div><div class="panel-title">Purchase history</div><div class="panel-subtitle">Posted purchases are preserved in the ledger.</div></div></div><div id="purchaseTable" class="empty">Loading purchases…</div></section>`;$('#newPurchase').onclick=openPurchase;try{const rows=await api('/purchases');$('#purchaseTable').innerHTML=rows.length?`<div class="table-wrap"><table><thead><tr><th>PURCHASE</th><th>SUPPLIER</th><th>DATE</th><th>AMOUNT</th><th>STATUS</th><th></th></tr></thead><tbody>${rows.map(p=>`<tr><td class="product-name">${esc(p.purchase_number)}</td><td>${esc(p.supplier_name)}</td><td>${new Date(p.purchased_at).toLocaleDateString()}</td><td class="money">${money(p.total_paisa)}</td><td><span class="badge ${p.status==='posted'?'':'red'}">${esc(p.status)}</span></td><td>${p.status==='posted'?`<button class="text-button" data-reverse-purchase="${esc(p.id)}">REVERSE</button>`:''}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No purchases yet. Add a supplier, then record a purchase.</div>';$$('[data-reverse-purchase]').forEach(b=>b.onclick=async()=>{if(!window.confirm('Purchase reverse karne se pehle uski supplier payments reverse honi chahiye. Stock kam hone ki surat mein reversal reject hoga. Jari rakhein?'))return;try{await api(`/purchases/${b.dataset.reversePurchase}/reverse`,{method:'POST',body:'{}'});toast('Purchase reverse ho gayi');purchasesPage()}catch(e){toast(e.message,true)}})}catch(e){toast(e.message,true)}}
async function openPurchase(){try{if(!state.suppliers)state.suppliers=await api('/suppliers');if(!state.products.length)state.products=await api('/products')}catch(e){toast(e.message,true);return}const options=state.suppliers.filter(x=>x.active).map(s=>`<option value="${esc(s.id)}">${esc(s.name)}</option>`).join('');const rows=state.products.filter(x=>x.active).map(p=>`<label class="cart-product"><div class="cart-product-info"><strong>${esc(p.name)}</strong><small>On hand: ${p.stock_quantity} · Latest cost ${money(p.purchase_cost_paisa)}</small></div><input data-purchase-check="${esc(p.id)}" type="checkbox"><input data-purchase-qty="${esc(p.id)}" type="number" min="1" step="1" value="1" style="width:60px;padding:6px" aria-label="Quantity for ${esc(p.name)}"><input data-purchase-cost="${esc(p.id)}" type="number" min="0" step="0.01" value="${(p.purchase_cost_paisa/100).toFixed(2)}" style="width:90px;padding:6px" aria-label="Unit cost for ${esc(p.name)}"></label>`).join('');openModal('Record a supplier purchase','Confirm the supplier, quantities, costs, and amount paid. Posting adds stock once.',`<div class="form-grid"><label class="field"><span>Supplier</span><select id="purchaseSupplier" required><option value="">Choose a supplier</option>${options}</select></label>${modalField('Invoice discount (Rs.)','purchaseDiscount','0','number',false,'min="0" step="0.01"')}${modalField('Amount paid now (Rs.)','purchasePaid','0','number',false,'min="0" step="0.01"')}<label class="field"><span>Payment method</span><select id="purchaseMethod"><option>Cash</option><option>Bank transfer</option><option>Other</option></select></label></div><div class="subtext" style="margin:8px 0">Select products, then enter quantity and purchase unit cost.</div><div class="cart-products">${rows||'<div class="empty">Add products before receiving a purchase.</div>'}</div>`,`<button class="button secondary" data-close>Cancel</button><button class="button primary" id="postPurchase">Post purchase</button>`,true);$('#postPurchase').onclick=async()=>{const supplier=$('#purchaseSupplier').value;const items=$$('[data-purchase-check]:checked').map(box=>({product_id:box.dataset.purchaseCheck,quantity:Number($(`[data-purchase-qty="${box.dataset.purchaseCheck}"]`).value),unit_cost_paisa:Math.round(Number($(`[data-purchase-cost="${box.dataset.purchaseCheck}"]`).value)*100)}));if(!supplier||!items.length){toast('Supplier aur kam az kam aik product choose karein.',true);return}const payload={id:crypto.randomUUID(),supplier_id:supplier,items,discount_paisa:Math.round(Number($('#purchaseDiscount').value||0)*100),paid_paisa:Math.round(Number($('#purchasePaid').value||0)*100),payment_method:$('#purchaseMethod').value};try{const result=await api('/purchases',{method:'POST',body:JSON.stringify(payload)});$('#modalHost').innerHTML='';toast('Purchase posted · '+result.purchase_number);state.products=[];purchasesPage()}catch(e){toast(e.message,true)}}}
